    13	  restore(record: DiagramRevision): DiagramRevision { return this.install(record, true); }
    14	  private install(record: DiagramRevision, deferred: boolean): DiagramRevision {
    15	    if (record.id !== record.diagram.revisionId || record.diagramId !== record.diagram.diagramId) throw Error('Invalid diagram revision identity');
    16	    const signature = JSON.stringify(record);
    17	    const prior = this.records.get(record.id);
    18	    if (prior) {
    19	      if (this.signatures.get(record.id) !== signature) throw Error('Diagram revision is immutable');
    20	      if (!deferred) this.get(record.id);
    21	      return prior;
    22	    }
    23	    if (!deferred) validateDiagram(record.diagram);
    24	    const stored = deepFreeze(structuredClone(record));
    25	    this.records.set(record.id, stored); this.signatures.set(record.id, signature);
    26	    if (deferred) this.pendingValidation.add(record.id);
    27	    return stored;
    28	  }
